WITH ids AS (SELECT arrayJoin((sumMapIfMerge(moves)).1) AS id FROM bestiary_mobs FINAL WHERE zone_id = {zone:Int64} AND mob_name = {name:String}) SELECT action_id AS id, argMax(animation, n) AS animation FROM (SELECT action_id, animation, count() AS n FROM actions WHERE category = 11 AND actor_is_mob AND action_id IN (SELECT id FROM ids) AND animation IS NOT NULL GROUP BY action_id, animation) GROUP BY action_id ORDER BY id
